package com.cpf.starter.soap;import java.time.Duration;import org.springframework.boot.context.properties.ConfigurationProperties;@ConfigurationProperties("cpf.integration.soap") public class CpfSoapProperties {private boolean enabled;private String endpoint,action;private Duration timeout=Duration.ofSeconds(10);private boolean wsSecurityRequired=true;public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getEndpoint(){return endpoint;}public void setEndpoint(String v){endpoint=v;}public String getAction(){return action;}public void setAction(String v){action=v;}public Duration getTimeout(){return timeout;}public void setTimeout(Duration v){timeout=v;}public boolean isWsSecurityRequired(){return wsSecurityRequired;}public void setWsSecurityRequired(boolean v){wsSecurityRequired=v;}public void validate(){if(!enabled)return;if(endpoint==null||endpoint.isBlank()||timeout.isNegative()||timeout.isZero())throw new IllegalStateException("SOAP endpoint/timeout required");}}
